<script setup lang="ts">
import {uiText} from '../features/i18n/interfaceLanguage'
import BookingServiceMark from '../components/BookingServiceMark.vue'
import {ref,computed,defineAsyncComponent} from 'vue'
import {isOperationalMode} from '../integrations/firebase/stagingConfig'
import {RouterLink} from 'vue-router'
import {useLabStore} from '../stores/lab'
import {useRoute} from 'vue-router'
const DevBookingWorkspace = isOperationalMode() ? defineAsyncComponent(() => import('./LiveBookingWorkspace.vue')) : import.meta.env.DEV ? defineAsyncComponent(() => import('./DevBookingWorkspace.vue')) : null
const bookingRoute=useRoute()
const bookingEmulatorMode=computed(()=>isOperationalMode() || (import.meta.env.DEV && bookingRoute.query.source==='emulator'))
const lab=useLabStore();const isCoach=computed(()=>lab.role==='coach')
const format=(date:Date)=>date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')
const month=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1)),selected=ref(format(new Date()))
const months=['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre']
const coaches=['Coach Test11','Coach Test22'],coach=ref(coaches[0])
const coachDot=(name:string)=>name===coaches[0]?'coach-blue':name===coaches[1]?'coach-yellow':'coach-other',service=ref(lab.role==='coach'?'Fighter e Pesi':'Fighter'),discipline=ref('MMA'),hour=ref(''),notice=ref('')
const tab=ref('prenota'),coachTab=ref('calendario'),coachFilter=ref('Tutti'),view=ref('Giorno'),state=ref('Prossimi')
const monthLabel=computed(()=>months[month.value.getMonth()]+' '+month.value.getFullYear())
const dateLong=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long',year:'numeric'})
const weekDays=computed(()=>{const d=new Date(selected.value+'T12:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return Array.from({length:7},(_,i)=>{const next=new Date(d);next.setDate(d.getDate()+i);return format(next)})})
const eventsOn=(day:string)=>filteredBookings.value.filter(b=>b.day===day&&(service.value==='Fighter e Pesi'||b.service.toLowerCase().startsWith(service.value.toLowerCase())))
const coachesOn=(day:string)=>[...new Set(eventsOn(day).map(b=>b.coach))]
function navigateDate(direction:number){if(view.value==='Mese'){shiftMonth(direction);return}const d=new Date(selected.value+'T12:00:00');d.setDate(d.getDate()+direction*(view.value==='Settimana'?7:1));selected.value=format(d);month.value=new Date(d.getFullYear(),d.getMonth(),1)}
function setSelectedDate(value:string){if(!value)return;selected.value=value;const d=new Date(value+'T12:00:00');month.value=new Date(d.getFullYear(),d.getMonth(),1)}

const cells=computed(()=>(()=>{const first=new Date(month.value.getFullYear(),month.value.getMonth(),1);const dow=(first.getDay()+6)%7;const total=new Date(month.value.getFullYear(),month.value.getMonth()+1,0).getDate();return [...Array(dow).fill(null),...Array.from({length:total},(_,i)=>i+1)]})())
function slotEnd(t:string){const [h,m]=t.split(':').map(Number);return String(h+1).padStart(2,'0')+':'+String(m).padStart(2,'0')}
const times=['09:00','10:00','11:00','12:00','15:30','16:00','17:00','18:00','19:00']
const bookings=computed(()=>lab.role==='coach'?lab.data.bookings:lab.myBookings)
const filteredBookings=computed(()=>bookings.value.filter(b=>(coachFilter.value==='Tutti'||b.coach===coachFilter.value)&&(state.value==='Storico'||b.status==='confirmed')).sort((a,b)=>a.day.localeCompare(b.day)))
const availability=ref<Record<string,{open:boolean,from:string,to:string}>>({Lunedì:{open:true,from:'15:00',to:'19:00'},Martedì:{open:true,from:'09:00',to:'13:00'},Mercoledì:{open:true,from:'09:00',to:'13:00'},Giovedì:{open:true,from:'09:00',to:'13:00'},Venerdì:{open:true,from:'09:00',to:'13:00'},Sabato:{open:true,from:'09:00',to:'13:00'},Domenica:{open:false,from:'09:00',to:'13:00'}})
const filterDate=ref(''),exceptionType=ref('Chiudi questo giorno'),timeFrom=ref('15:00'),timeTo=ref('19:00'),holidayFrom=ref(''),holidayTo=ref('')
const durationFighter=ref('60 minuti'),durationPesi=ref('60 minuti'),advance=ref(12),cancel=ref(12),horizon=ref(30),slots=ref(true)

function shiftMonth(n:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+n,1);selected.value=format(month.value);hour.value=''}
function dateInMonth(day:number){return format(new Date(month.value.getFullYear(),month.value.getMonth(),day))}
function chooseDay(day:number){selected.value=dateInMonth(day);hour.value='';notice.value=''}
function book(){if(!hour.value){notice.value='Seleziona prima un orario libero.';return}if(lab.data.bookings.some(b=>b.day===selected.value&&b.hour===hour.value&&b.coach===coach.value&&b.status==='confirmed')){notice.value='Questo orario è già occupato nella demo.';return}lab.createBooking({athlete:lab.athlete?.name??'Atleta Demo',coach:coach.value,service:service.value+' · '+discipline.value,day:selected.value,hour:hour.value});notice.value='Prenotazione salvata solo nel browser (demo). Nessun appuntamento reale.';tab.value='mie'}
function daysForDate(date:string){return lab.data.bookings.filter(b=>b.day===date&&b.status==='confirmed')}
function saveAvailability(){notice.value='Disponibilità aggiornate nella sessione demo, senza scritture Firebase.'}
</script>
<template><component :is="DevBookingWorkspace" v-if="bookingEmulatorMode && DevBookingWorkspace"/><div v-else class="stack" style="gap:18px"><div class="booking-intro"><span class="eyebrow">LION FIT · SERVIZI</span><h1 style="margin:4px 0">{{uiText("Prenotazioni")}}</h1><p class="muted">Area {{isCoach?'Coach':'Atleta'}} · {{isCoach?'Pannello Coach':lab.athlete?.name}}</p><div class="row booking-top-controls"><RouterLink class="ghost booking-return booking-control" :to="isCoach?'/coach':'/home'">← Torna all’app</RouterLink><span class="pill booking-live-pill">● Online</span></div></div>
 <template v-if="!isCoach">
 <div class="booking-tabs booking-main-tabs"><button :class="{selected:tab==='prenota'}" @click="tab='prenota'">{{uiText("Prenota")}}</button><button :class="{selected:tab==='mie'}" @click="tab='mie'">{{uiText("Le mie prenotazioni")}}</button></div>
 <template v-if="tab==='prenota'"><h2 class="booking-section-title">{{uiText("1. Scegli il tuo percorso")}}</h2><div class="booking-choices booking-v1-services"><button class="booking-choice booking-service-card" :class="{selected:service==='Fighter'}" @click="service='Fighter'"><BookingServiceMark kind="fighter"/><div><div class="booking-service-badge">SESSIONE PRIVATA</div><strong>FIGHTER</strong><small>MMA, Boxe, K-1, Karate tradizionale e Karate agonistico. Allena la tecnica con il coach che preferisci.</small></div><div class="booking-service-cta">Scegli Fighter →</div></button><button class="booking-choice booking-service-card" :class="{selected:service==='Pesi'}" @click="service='Pesi'"><BookingServiceMark kind="pesi"/><div><div class="booking-service-badge">PROGRAMMA PERSONALIZZATO</div><strong>PESI</strong><small>Costruisci una scheda di pesistica insieme al coach in un incontro privato dedicato ai tuoi obiettivi.</small></div><div class="booking-service-cta">Scegli Pesi →</div></button></div>
 <h2 class="booking-section-title">2. Seleziona il coach</h2><div class="grid2"><button v-for="c in coaches" :key="c" class="action-card" :class="{active:coach===c}" @click="coach=c"><span class="action-icon">{{c==='Coach Test11'?'T':'R'}}</span><div><strong>{{c}}</strong><small>Lezione privata {{service}} · 60 min</small></div><span class="arrow">›</span></button></div>
 <h2 class="booking-section-title">{{uiText("3. Tipo di incontro")}}</h2><div class="panel"><label>Disciplina / motivo dell'appuntamento</label><select v-model="discipline"><option>MMA</option><option>Boxe</option><option>K-1</option><option>Grappling</option><option>Pesistica</option><option>Preparazione atletica</option></select></div>
 <h2 class="booking-section-title">{{uiText("4. Scegli giorno e orario")}}</h2><section class="panel"><div class="row between"><button class="secondary" @click="shiftMonth(-1)">‹</button><strong>{{monthLabel}}</strong><button class="secondary" @click="shiftMonth(1)">›</button></div><div class="booking-calendar" style="margin-top:26px"><div v-for="(x,i) in ['L','M','M','G','V','S','D']" :key="i" class="muted" style="text-align:center">{{x}}</div><template v-for="(d,i) in cells" :key="i"><div v-if="d===null"></div><button v-else class="booking-day" :class="{selected:selected===dateInMonth(d),disabled:new Date(dateInMonth(d)+'T00:00:00').getDay()===0}" @click="chooseDay(d)">{{d}}<small>Libero</small></button></template></div><p class="small muted" style="margin-top:15px">Verde: ci sono orari prenotabili. Grigio: chiuso, completo o fuori periodo. Nella demo la disponibilità è illustrativa.</p></section>
 <section class="panel"><h2>{{selected}}</h2><div class="times"><button v-for="t in times" :key="t" :class="{selected:hour===t}" :disabled="daysForDate(selected).some(b=>b.coach===coach&&b.hour===t)" @click="hour=t">{{t}}–{{slotEnd(t)}}</button></div><p class="small muted" style="margin-top:13px">Gli orari occupati non sono selezionabili nella simulazione locale.</p></section>
 <section class="panel"><span class="eyebrow">{{uiText("RIEPILOGO")}}</span><h2 style="margin:10px 0">{{hour?selected+' · '+hour:'Seleziona un orario libero'}}</h2><p class="muted">{{coach}} · 60 minuti · {{service}}</p><button class="primary" :disabled="!hour" @click="book">Conferma prenotazione (demo)</button></section></template>
 <section v-else class="panel"><h2>{{uiText("Le mie prenotazioni")}}</h2><div v-for="b in bookings" :key="b.id" class="list-row"><div><b>{{b.day}} · {{b.hour}}</b><p class="small muted">{{b.coach}} · {{b.service}} · {{b.status==='confirmed'?'Confermata':'Annullata'}}</p></div><button v-if="b.status==='confirmed'" class="danger" @click="lab.cancelBooking(b.id)">Disdici</button></div><p v-if="!bookings.length" class="muted">Nessun appuntamento di prova.</p></section>
 </template>
 <template v-else><div class="booking-tabs"><button :class="{selected:coachTab==='calendario'}" @click="coachTab='calendario'">Calendario coach</button><button :class="{selected:coachTab==='disponibilita'}" @click="coachTab='disponibilita'">Disponibilità</button></div>
 <template v-if="coachTab==='calendario'"><section class="panel"><div class="row between"><div><h2>{{uiText("Calendario condiviso")}}</h2><p class="muted small">Un calendario, filtri per coach. Le prenotazioni cambiano senza ricaricare la pagina.</p></div><span class="pill pill-neutral">{{filteredBookings.length}} {{uiText("appuntamenti")}}</span></div><div class="booking-tabs"><button v-for="c in ['Tutti',...coaches]" :key="c" :class="{selected:coachFilter===c}" @click="coachFilter=c"><i v-if="c!=='Tutti'" class="coach-dot" :class="coachDot(c)" aria-hidden="true"/> {{c}}</button></div><div class="divider"/><div class="row between"><div class="booking-tabs"><span class="muted small">{{uiText("Vista")}}</span><button v-for="v in ['Giorno','Settimana','Mese']" :key="v" :class="{selected:view===v}" @click="view=v">{{v}}</button></div><div class="booking-tabs"><button v-for="v in ['Prossimi','Storico']" :key="v" :class="{selected:state===v}" @click="state=v">{{v}}</button></div></div></section>
 <div class="row booking-date-controls"><button class="secondary" @click="navigateDate(-1)">‹</button><input :value="selected" type="date" @change="setSelectedDate(($event.target as HTMLInputElement).value)" style="width:175px"/><button class="secondary" @click="navigateDate(1)">›</button><select v-model="service" style="max-width:180px"><option>{{uiText("Fighter e Pesi")}}</option><option>Fighter</option><option>{{uiText("Pesi")}}</option></select></div>
 <section v-if="view==='Giorno'" class="panel booking-period"><h3>{{dateLong(selected)}}</h3><div v-if="!eventsOn(selected).length" class="empty-event">{{uiText("Nessun appuntamento.")}}</div><article v-for="b in eventsOn(selected)" :key="b.id" class="event-item"><strong><i class="coach-dot" :class="coachDot(b.coach)" aria-hidden="true"/> {{b.hour}} · {{b.athlete}}</strong><span>{{b.service}} · {{b.coach}}</span></article></section>
 <section v-else-if="view==='Settimana'" class="panel booking-period"><h3>{{uiText("Settimana del")}} {{dateLong(weekDays[0])}}</h3><div v-for="day in weekDays" :key="day" class="week-event-day"><strong>{{dateLong(day)}}</strong><span class="event-count">{{eventsOn(day).length}}</span><div v-if="!eventsOn(day).length" class="muted small">Nessuno</div><article v-for="b in eventsOn(day)" :key="b.id" class="event-item"><i class="coach-dot" :class="coachDot(b.coach)" aria-hidden="true"/> {{b.hour}} · {{b.athlete}} · {{b.coach}} · {{b.service}}</article></div></section>
 <section v-else class="panel booking-period"><h3>{{monthLabel}}</h3><div class="coach-month-grid"><span v-for="(name,i) in ['L','M','M','G','V','S','D']" :key="i" class="coach-month-weekday">{{name}}</span><template v-for="(day,i) in cells" :key="i"><span v-if="day===null" class="month-empty"/><button v-else class="coach-month-day" :class="{selected:selected===dateInMonth(day)}" @click="setSelectedDate(dateInMonth(day))"><b>{{day}}</b><small>{{eventsOn(dateInMonth(day)).length?eventsOn(dateInMonth(day)).length+' appuntamenti':'—'}}</small><span class="coach-month-dots" :aria-label="coachesOn(dateInMonth(day)).join(', ')"><i v-for="name in coachesOn(dateInMonth(day))" :key="name" class="coach-dot" :class="coachDot(name)"/></span></button></template></div></section></template>
 <template v-else><section class="panel"><h2>Impostazioni attività</h2><p class="muted">Spegni per non ricevere nuovi appuntamenti.</p><label class="checkline"><input v-model="slots" type="checkbox"/> Fighter abilitato</label><label class="checkline"><input v-model="slots" type="checkbox"/> Pesi abilitato</label></section>
 <section class="panel"><h2>Settimana tipo</h2><p class="muted small">Orari da lunedì a domenica: ON / OFF per ogni giorno. Fasce di 30 minuti e appuntamenti da 60 a 120 minuti.</p><div class="availability-grid"><div v-for="(v,k) in availability" :key="k" class="line-card"><div class="row between"><b>{{k}}</b><input v-model="v.open" type="checkbox"/></div><div class="grid2"><select v-model="v.from"><option v-for="n in 25" :key="n">{{String(7+Math.floor((n-1)/2)).padStart(2,'0')}}:{{(n-1)%2?'30':'00'}}</option></select><select v-model="v.to"><option v-for="n in 28" :key="n">{{String(8+Math.floor((n-1)/2)).padStart(2,'0')}}:{{(n-1)%2?'30':'00'}}</option></select></div><button class="ghost">+ Aggiungi fascia</button></div></div></section>
 <section class="panel"><h2>Impostazioni avanzate, periodi, ferie ed eccezioni</h2><p class="muted small">Durata delle lezioni, preavviso, disdetta, periodo e giorni di chiusura.</p><div class="grid2"><div><label>{{uiText("Durata Fighter")}}</label><select v-model="durationFighter"><option>{{uiText("60 minuti")}}</option><option>90 minuti</option><option>{{uiText("120 minuti")}}</option></select></div><div><label>{{uiText("Durata Pesi")}}</label><select v-model="durationPesi"><option>{{uiText("60 minuti")}}</option><option>90 minuti</option><option>{{uiText("120 minuti")}}</option></select></div><div><label>Preavviso minimo (ore)</label><input v-model.number="advance" type="number"/></div><div><label>Disdetta almeno entro (ore)</label><input v-model.number="cancel" type="number"/></div><div><label>{{uiText("Prenotabile entro (giorni)")}}</label><input v-model.number="horizon" type="number"/></div></div><h3 style="margin-top:20px">{{uiText("Eccezioni e ferie")}}</h3><div class="grid2"><div><label>{{uiText("Giorno")}}</label><input v-model="filterDate" type="date"/></div><div><label>Tipo modifica</label><select v-model="exceptionType"><option>{{uiText("Chiudi questo giorno")}}</option><option>{{uiText("Orario speciale")}}</option></select></div><div><label>{{uiText("Dalle")}}</label><input v-model="timeFrom" type="time"/></div><div><label>{{uiText("Alle")}}</label><input v-model="timeTo" type="time"/></div></div><button class="ghost" @click="saveAvailability">{{uiText("+ Aggiungi eccezione")}}</button><h3 style="margin-top:19px">Ferie e chiusure per un periodo</h3><div class="grid2"><label>{{uiText("Dal")}}<input v-model="holidayFrom" type="date"/></label><label>Al<input v-model="holidayTo" type="date"/></label></div><button class="ghost" @click="saveAvailability">+ Chiudi il periodo</button><div class="notice" style="margin-top:16px">Modalità demo: queste impostazioni non modificano disponibilità Firestore reali.</div><button class="primary wide" style="margin-top:12px" @click="saveAvailability">Salva disponibilità e prepara gli orari (demo)</button></section></template>
 </template><div v-if="notice" class="notice notice-success">{{notice}}</div><p class="small muted">Lion Fit · Prenotazioni Beta 0.29.7 · Interfaccia dimostrativa Vue: nessun invio ai servizi reali.</p>
 </div></template>
